import * as THREE from 'three';

const CEILING = 5.6;
const PORTAL_HEIGHT = 4.31;

// A single roof lantern gives each gallery a legible source of daylight.
// Its opening is part of the ceiling geometry, and the splayed reveal rises
// above the room. All dimensions use the existing metre-scale floor plan.
export function galleryRooflight(room) {
  const width = Math.min(3.05, room.localWidth * .24);
  const depth = Math.min(9.2, Math.max(4.1, room.localDepth * .48));
  return { width, depth, radius: .46, ceiling: CEILING, crown: 6.32 };
}

function roundedOutline(width, depth, radius, segments = 8) {
  const points = [];
  const corners = [
    [width / 2 - radius, depth / 2 - radius, 0],
    [-width / 2 + radius, depth / 2 - radius, Math.PI / 2],
    [-width / 2 + radius, -depth / 2 + radius, Math.PI],
    [width / 2 - radius, -depth / 2 + radius, Math.PI * 1.5],
  ];
  for (const [x, z, start] of corners) for (let i = 0; i <= segments; i++) {
    const angle = start + i / segments * Math.PI / 2;
    points.push(new THREE.Vector2(x + Math.cos(angle) * radius, z + Math.sin(angle) * radius));
  }
  return points;
}

function pathFromPoints(points, Path = THREE.Path) {
  const path = new Path();
  points.forEach((point, index) => index ? path.lineTo(point.x, point.y) : path.moveTo(point.x, point.y));
  path.closePath();
  return path;
}

function roofRevealGeometry(roof) {
  // Three rings ease the chamfer into its upper edge. The broad lower slope
  // stays quiet, while the short upper return gives the diffuser real depth.
  const rings = [
    { inset: 0, y: roof.ceiling },
    { inset: .33, y: roof.crown - .1 },
    { inset: .33, y: roof.crown },
  ].map(({ inset, y }) => ({
    points: roundedOutline(roof.width - inset * 2, roof.depth - inset * 2, Math.max(.1, roof.radius - inset)), y,
  }));
  const count = rings[0].points.length, positions = [], uvs = [], indices = [];
  rings.forEach((ring, level) => ring.points.forEach((point, index) => {
    positions.push(point.x, ring.y, point.y);
    uvs.push(index / count, level / (rings.length - 1));
  }));
  for (let level = 0; level < rings.length - 1; level++) for (let index = 0; index < count; index++) {
    const next = (index + 1) % count;
    const a = level * count + index, b = level * count + next;
    const c = (level + 1) * count + next, d = (level + 1) * count + index;
    indices.push(a, c, b, a, d, c);
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

/**
 * Return static architectural meshes for the existing scene batcher.
 * This supplies room ceilings, so the caller omits the original solid lids.
 * It adds no light, texture, interaction target or walking obstruction.
 */
export function createGalleryDetailMeshes(plan, { wall, floor }) {
  const meshes = [];
  const reveal = wall.clone();
  reveal.side = THREE.DoubleSide;
  const daylight = new THREE.MeshBasicMaterial({ color: '#e7e3d9', toneMapped: false, side: THREE.DoubleSide });
  const stone = floor.clone();
  stone.color.multiplyScalar(.94);
  stone.roughness = .86;
  const joint = new THREE.MeshBasicMaterial({ color: '#6a645c', transparent: true, opacity: .18, depthWrite: false });

  function add(geometry, material, kind, roomIndex, position = [0, 0, 0], rotation = 0) {
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.fromArray(position);
    mesh.rotation.y = rotation;
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    mesh.userData.spatialDetail = kind;
    mesh.userData.roomIndex = roomIndex;
    meshes.push(mesh);
    return mesh;
  }
  function box(width, height, depth, material, kind, roomIndex, x, y, z, rotation = 0) {
    return add(new THREE.BoxGeometry(width, height, depth), material, kind, roomIndex, [x, y, z], rotation);
  }

  for (const room of plan.rooms) {
    const roof = galleryRooflight(room);
    const halfWidth = room.localWidth / 2, halfDepth = room.localDepth / 2;
    const ceilingShape = new THREE.Shape([
      new THREE.Vector2(-halfWidth, -halfDepth), new THREE.Vector2(halfWidth, -halfDepth),
      new THREE.Vector2(halfWidth, halfDepth), new THREE.Vector2(-halfWidth, halfDepth),
    ]);
    ceilingShape.holes.push(pathFromPoints(roundedOutline(roof.width, roof.depth, roof.radius)));
    const ceiling = new THREE.ShapeGeometry(ceilingShape).rotateX(Math.PI / 2);
    add(ceiling, wall, 'ceiling', room.index, [room.x, roof.ceiling, room.z], room.angle);
    add(roofRevealGeometry(roof), reveal, 'roof-reveal', room.index, [room.x, 0, room.z], room.angle);
    const diffuserShape = pathFromPoints(roundedOutline(roof.width - .66, roof.depth - .66, .13), THREE.Shape);
    const diffuser = new THREE.ShapeGeometry(diffuserShape).rotateX(Math.PI / 2);
    add(diffuser, daylight, 'roof-diffuser', room.index, [room.x, roof.crown, room.z], room.angle);
  }

  // The wall foot is a narrow construction joint. It stops exactly where
  // each wall stops, keeping every threshold continuous and unobstructed.
  for (const segment of plan.walls) {
    box(segment.width + .012, .046, segment.depth + .012, joint, 'wall-foot', segment.room,
      segment.x, .024, segment.z);
  }

  for (const door of plan.doors) for (let side = 0; side < 2; side++) {
    const point = door.points[side], room = plan.rooms[side ? door.b : door.a];
    const normalX = Math.abs(point[0] - room.x) > room.width / 2 - .1;
    const rotation = normalX ? Math.PI / 2 : 0;
    const tangent = [Math.cos(rotation), -Math.sin(rotation)];
    // Jambs sit outside the clear opening. The fine stone return is visible
    // on the wall and through the thickness of the doorway.
    for (const sign of [-1, 1]) {
      const offset = sign * (door.width / 2 + .055);
      box(.11, PORTAL_HEIGHT, .34, stone, 'portal-jamb', room.index,
        point[0] + tangent[0] * offset, PORTAL_HEIGHT / 2, point[1] + tangent[1] * offset, rotation);
    }
    box(door.width + .22, .11, .34, stone, 'portal-head', room.index,
      point[0], PORTAL_HEIGHT + .055, point[1], rotation);
    box(door.width, .006, .34, stone, 'threshold', room.index,
      point[0], -.026, point[1], rotation);
  }
  return meshes;
}
